$ErrorActionPreference='Stop'
Write-Host 'BUMBLEBEE: MYTH; HONOR; GOLD/PLATINUM MERIT; WINGS; RUNES'
Write-Host 'AIZVER SPELI UN IZLOGOJIES; TIKAI TESTA VM 192.168.56.101; AR REZERVES KOPIJU'
$bytes=[Convert]::FromBase64String('')
$sha=[Security.Cryptography.SHA256]::Create()
try { $actual=([BitConverter]::ToString($sha.ComputeHash($bytes))).Replace('-','').ToLowerInvariant() } finally { $sha.Dispose() }
if($actual -ne 'f011a179fd8b43588036dcf8b9aa25d782b0e480478c5048db4b7a7867dba4ba'){throw 'GRANT_PAYLOAD_HASH_DIFFERS'}
$code=[Text.Encoding]::UTF8.GetString($bytes)
$stamp=Get-Date -Format 'yyyyMMdd-HHmmss'
$receipt=Join-Path $env:USERPROFILE ('Downloads\BumbleBee-Masteries-Receipt-'+$stamp+'.txt')
$lines=@($code | & ssh.exe root@192.168.56.101 python3 - --apply)
$exit=$LASTEXITCODE
$lines | Set-Content -LiteralPath $receipt -Encoding UTF8
$lines | ForEach-Object { Write-Host $_ }
Write-Host ('REPORT='+$receipt)
if($exit -ne 0 -or !($lines | Select-String -SimpleMatch -Pattern 'BUMBLEBEE_MASTERIES_CONFIRMED;','BUMBLEBEE_MASTERIES_ALREADY_GRANTED;')){throw 'PIESKIRUMS_NAV_APSTIPRINATS; ATSUTI_IZVADI'}
Write-Host 'GATAVS; PALAID SPELI AR F:\CABAL_291_TEST\Start.bat'
